import { Q, fetchPolicies } from 'cozy-client';
import { Contact, Group } from '../models';
var DEFAULT_CACHE_TIMEOUT_QUERIES = 9 * 60 * 1000;
var defaultFetchPolicy = fetchPolicies.olderThan(DEFAULT_CACHE_TIMEOUT_QUERIES);
export var fetchApps = function fetchApps() {
  return {
    definition: Q('io.cozy.apps'),
    options: {
      as: 'io.cozy.apps',
      fetchPolicy: defaultFetchPolicy
    }
  };
};
export var buildSharingsByIdQuery = function buildSharingsByIdQuery(sharingId) {
  return {
    definition: Q('io.cozy.sharings').getById(sharingId),
    options: {
      as: "io.cozy.sharings/".concat(sharingId),
      fetchPolicy: defaultFetchPolicy
    }
  };
};
export var buildReachableContactsQuery = function buildReachableContactsQuery() {
  return {
    definition: Q(Contact.doctype).where({
      _id: {
        $gt: null
      }
    }).partialIndex({
      trashed: {
        $or: [{
          $eq: false
        }, {
          $exists: false
        }]
      },
      $or: [{
        cozy: {
          $not: {
            $size: 0
          }
        }
      }, {
        email: {
          $not: {
            $size: 0
          }
        }
      }]
    }).indexFields(['_id']).limitBy(1000),
    options: {
      as: 'io.cozy.contacts/reachable'
    }
  };
};
export var buildContactGroupsQuery = function buildContactGroupsQuery() {
  return {
    definition: Q(Group.doctype),
    options: {
      as: "io.cozy.contacts.groups",
      fetchPolicy: defaultFetchPolicy
    }
  };
};
export var buildUnreachableContactsWithGroupsQuery = function buildUnreachableContactsWithGroupsQuery() {
  return {
    definition: Q(Contact.doctype).where({
      _id: {
        $gt: null
      }
    }).partialIndex({
      trashed: {
        $or: [{
          $eq: false
        }, {
          $exists: false
        }]
      },
      cozy: {
        $size: 0
      },
      email: {
        $size: 0
      },
      'relationships.groups.data': {
        $exists: true
      }
    }).indexFields(['_id']).limitBy(1000),
    options: {
      as: 'io.cozy.contacts/unreachable-with-groups',
      fetchPolicy: defaultFetchPolicy
    }
  };
};
export var buildInstanceSettingsQuery = function buildInstanceSettingsQuery() {
  return {
    definition: Q('io.cozy.settings').getById('io.cozy.settings.instance'),
    options: {
      as: 'io.cozy.settings/instance',
      singleDocData: true
    }
  };
};